{
  "name": "loss_rank_blend_tanh_advantage",
  "intuition": "Leverage advantage signals to modulate a tanh-transformed rank difference, blending margin and rank paradigms with nonlinear smoothing to capture nuanced ordered preference relations beyond simple margin losses.",
  "pseudocode": "gap = advantage_w - advantage_l\nmargin = tanh(alpha * (log_prob_w - log_prob_l))\nrank_blend = gap * margin\nloss = -mean(weight * rank_blend)",
  "hyperparams": {
    "paradigm_family": "pairwise_rank_blend",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["tanh", "sub", "mul", "neg", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    alpha = float(extra.get('alpha', 1.0))\n    gap = ops.sub(adv_w, adv_l)\n    margin = ops.tanh(ops.mul(alpha, ops.sub(lpw, lpl)))\n    rank_blend = ops.mul(gap, margin)\n    weighted_loss = ops.mul(weight, rank_blend)\n    loss = ops.neg(ops.mean(weighted_loss))\n    return loss"
}

{
  "name": "pairwise_pref_loss",
  "intuition": "This loss compares pairs of sequences based on their advantage signals, encouraging the model to prefer sequences with higher advantage scores. By integrating advantage differences with a sigmoid transform, the loss smoothly penalizes pairwise preferences aligned with the advantage signals, thus promoting better ordering of sequences. It leverages pairwise comparisons to directly optimize for the relative preference signal, which is effective in preference-based RL settings.",
  "pseudocode": "loss = -mean( logsigmoid( advantage_w - advantage_l ) * weight )",
