  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    cost_gap = batch[\"cost_gap\"]\n    score = ops.logsigmoid( ops.sub( log_prob_w, log_prob_l ) + ops.mul( alpha, cost_gap ) )\n    weighted_score = ops.mul( score, batch[\"weight\"] )\n    loss = ops.mean( weighted_score )\n    return loss"
