  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    cost_gap = batch['cost_gap']\n    weights = batch.get('weight', None)\n    diff = ops.sub(log_prob_w, log_prob_l)\n    scaled_diff = ops.mul(diff, cost_gap)\n    loss_terms = ops.logsigmoid(scaled_diff)\n    loss = ops.neg(ops.mean(loss_terms))\n    return loss"
