{
  "name": "loss_tanh_advantage_margin",
  "intuition": "Use a pairwise margin loss modulated by the advantage gap, employing a tanh-based smooth margin instead of logsigmoid, and aggregate by sum for sensitivity to pairwise differences.",
  "pseudocode": "margin = tanh(scale * (log_prob_w - log_prob_l) - beta * advantage_gap)\nloss = relu(-margin) * weight\nloss = sum(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin_marginbased",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "sum",
    "constraint_family": "relu_nonnegative_margin"
  },
  "operators_used": ["tanh", "relu", "mul", "sub", "sum", "neg"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    adv_gap = batch.get('advantage_gap', lpw.new_zeros(lpw.shape))\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    beta = float(extra.get('hyperparams', {}).get('beta', 0.5))\n\n    margin_raw = ops.tanh(ops.sub(ops.mul(scale, ops.sub(lpw, lpl)), ops.mul(beta, adv_gap)))\n    margin_neg_part = ops.relu(ops.neg(margin_raw))\n\n    weighted_loss = ops.mul(margin_neg_part, weight)\n\n    return ops.sum(weighted_loss)"
}

{
  "name": "loss_margin_rankblend_softplus_advantage",
  "intuition": "Instead of a pure margin loss with a logsigmoid link, this loss blends margin and ranking signals using a softplus penalty, weighted adaptively by an advantage gap to prioritize informative pairs.",
  "pseudocode": "adv_gap = batch['advantage_gap']\nmargin = (log_prob_w - log_prob_l)\nweight = batch.get('weight', ones)\nadaptive_weight = sigmoid(5 * adv_gap)  # emphasize strong advantages\nraw_loss = softplus(-margin) * adaptive_weight\nloss = mean(weight * raw_loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_rankblend",
    "signal_family": "advantage_gap",
    "link_family": "softplus",
    "agg_family": "mean",
    "constraint_family": "sigmoid_adaptive_weighting"
  },
  "operators_used": ["sigmoid", "softplus", "mean", "mul", "sub", "neg"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_gap = batch['advantage_gap']\n    adaptive_w = ops.sigmoid(ops.mul(ops.float_tensor(5.0, device=lpw.device, dtype=lpw.dtype), adv_gap))\n    margin = ops.sub(lpw, lpl)\n    raw_loss = ops.mul(ops.softplus(ops.neg(margin)), adaptive_w)\n    weighted_loss = ops.mul(raw_loss, weight)\n    return ops.mean(weighted_loss)\n"
}
